// Script loop 1a26a: 1a296 posts A1 and re-enters 1a278, so a stop at 1a0b6 is reached once per command; the
// split run ends in the same state as the continuous one. Placement 1a442 split at 1a470/28ae/43e08/1a500/1a514.
void script_loop(Bytes&ram){put(ram,0x10d412,4,SCR);put(ram,0x10d418,2,5);put(ram,0x10d416,2,0);
 put(ram,SCR,2,0x28);put(ram,SCR+2,2,3);put(ram,SCR+4,2,0x34);put(ram,SCR+6,2,1);put(ram,SCR+8,2,0x28);put(ram,SCR+10,2,9);put(ram,SCR+12,2,0x28);}
void placement(Bytes&ram){put(ram,0x10d40e,4,REC);put(ram,0x10d3a6,2,0x10);put(ram,0x10d3f2,2,0xff00);put(ram,0x10d3f4,2,0x100);put(ram,0x10d3f6,2,0xff00);
 put(ram,0x10d3f8,2,0x100);put(ram,0x104ca0,2,1);put(ram,0x104c9c,4,OBJ);put(ram,PAR+0x10,2,7);put(ram,PAR+8,4,PAR+0x40);
 put(ram,REC+2,2,4);put(ram,REC+4,2,0x123);put(ram,REC+6,2,0x456);put(ram,REC+12,4,0x4a000);put(ram,REC+0x10,4,0x11223344);}
void split(){
 {Bytes whole=zero_ram();script_loop(whole);State w=state(0x1a26a);Out o;assert(run(whole,w,STOP,o)&&quiet(o));
  assert(get(whole,0x10d416,2)==9&&get(whole,0x10d412,4)==SCR+12&&(get(whole,0x10d3cc,1)&3U)==2);
  Bytes ram=zero_ram();script_loop(ram);State s=state(0x1a26a);unsigned int commands=0;
  for(;;){Out q;assert(run(ram,s,0x1a0b6,q)||true);if(s.pc!=0x1a0b6)break;++commands;
   assert(s.a[1]==SCR+4*(commands-1)&&get(ram,s.a[7],4)==0x1a296);Out r;assert(run(ram,s,0x1a296,r)&&s.a[1]==SCR+4*commands);
   if(commands==3)break;}
  Out q;assert(commands==3&&run(ram,s,STOP,q)&&ram==whole&&same(s,w));
  // A stop at 1a296 that is reached only after the first command; then the wait (3) is not above the phase (5).
  Bytes r2=zero_ram();script_loop(r2);State t=state(0x1a26a);Out q2;assert(run(r2,t,0x1a296,q2)&&get(r2,0x10d416,2)==3&&t.a[1]==SCR+4);}
 {Bytes whole=zero_ram();placement(whole);State w=state(0x1a442);Out o;assert(run(whole,w,STOP,o)&&quiet(o));
  assert(get(whole,0x10d40e,4)==REC+0x14&&get(whole,OBJ+0x76,4)==0x11223344&&get(whole,0x104ca0,2)==0);
  const std::uint32_t stops[]={0x1a470,0x19802,0x1a484,0x28ae,0x1a4ee,0x43e08,0x43e38,0x1a500,0x1a514,0x1a51a,STOP};
  Bytes ram=zero_ram();placement(ram);State s=state(0x1a442);
  for(unsigned int i=0;i<sizeof(stops)/sizeof(stops[0]);++i){Out q;assert(run(ram,s,stops[i],q)&&s.pc==stops[i]);}
  assert(ram==whole&&same(s,w));}
}
// Opcode index policy (1a0b8 JMP 1a0bc+D7.W, no range check): a computed block start runs, a non-start even PC in
// U5 is rejected, odd fails alignment, PCs outside every executor are unsupported. Table index (1a086/1a09e) is read
// through the declared windows only. 197a2 needs the known C of 18c06.
void policy(){
 struct Op {std::uint32_t op;const char*message;};
 const Op ops[]={{0x52,"unsupported animation script placement PC"},{0x4e,"unsupported animation script placement PC"},
  {0xfffc,"unsupported animation script placement PC"},{0x1,"unaligned animation machine PC"},{0x7fff,"unaligned animation machine PC"},
  {0x7ffe,"unsupported animation machine PC"},{0x1000,"unsupported animation scene update PC"}}; // 1000 -> 1b0bc (U4 interior)
 for(unsigned int i=0;i<sizeof(ops)/sizeof(ops[0]);++i){Bytes ram=zero_ram();put(ram,SP,4,0x1a296);put(ram,SCR,2,ops[i].op);
  reject(ram,state(0x1a0b6),0x1a296,ops[i].message);}
 // From the script loop: the second command is out of range after the first one's writes.
 {Bytes ram=zero_ram();script_loop(ram);put(ram,SCR+4,2,0x52);reject(ram,state(0x1a26a),STOP,"unsupported animation script placement PC");}
 // Table index: odd (1a08f) and beyond the 16-byte window (1a09e is code, not declared).
 {Bytes ram=zero_ram();State s=state(0x1a086);s.d[7]=1;reject(ram,s,STOP,"even WORD/LONG");
  s=state(0x1a086);s.d[7]=0x10;reject(ram,s,STOP,"missing program bus ROM unit");
  s=state(0x1a09e);s.d[7]=0xfffc;reject(ram,s,STOP,"missing program bus ROM unit");
  put(ram,SP,4,0x1a296);put(ram,SCR,2,0x14);put(ram,SCR+2,2,0x10);reject(ram,state(0x1a0b6),0x1a296,"missing program bus ROM unit");}
 // 197a2 (BCC after BSR 18c06): Unknown carry is a checked error; Clear -> 197b2, Set -> 197a6.
 {Bytes ram=zero_ram();State s=state(0x197a2);s.carry=ms5::AnimationCarryUnknown;reject(ram,s,STOP,"script placement caller requires known carry");
  s=state(0x197a2);s.carry=ms5::AnimationCarryClear;Out o;assert(run(ram,s,0x197b2,o)&&s.carry==ms5::AnimationCarryClear&&quiet(o));
  s=state(0x197a2);s.carry=ms5::AnimationCarrySet;assert(run(ram,s,0x197a6,o)&&s.carry==ms5::AnimationCarrySet);}
 // Opcode 04 bank side effect persists to the end of the call: entered with bank 2000 (300000) and 100010=1.
 {Bytes ram=zero_ram();put(ram,SP,4,0x1a296);put(ram,0x100010,2,1);put(ram,SCR,2,4);put(ram,SCR+2,2,3);put(ram,DESC+0x30,2,0xffff);
  put(ram,SCR+4,2,0x28);State s=state(0x1a0b6);Out o;o.dev.bank_base=0x300000;assert(run(ram,s,0x1a296,o));
  assert(o.dev.bank_base==0x200000&&get(ram,0x100010,2)==0&&s.a[0]==DESC+0x32&&s.a[1]==SCR+4&&o.ports.size()==3&&o.ports[2].address==0x300001&&
   o.ports[0].address==0x2ffff2&&o.ports[0].value==0x1000&&o.ports[1].address==0x2ffff0&&o.ports[1].value==0);
  // The next command (28) does not touch the bank (8da2 also kicked the watchdog 300001 above).
  s.pc=0x1a0b6;s.a[7]=SP;put(ram,SP,4,0x1a296);Out q;q.dev.bank_base=0x200000;assert(run(ram,s,0x1a296,q)&&quiet(q)&&get(ram,0x10d416,2)==0);}
}
// Odd An / A7 accesses and odd pointers loaded from the script, record or table; failures roll back.
void odd(){
 struct Odd {std::uint32_t pc;unsigned int reg;const char*message;};
 const Odd odd[]={{0x1a0b6,1,"even WORD/LONG"},{0x1a11c,1,"even WORD/LONG"},{0x1a146,1,"even WORD/LONG"},{0x1a174,7,"even WORD/LONG"},
  {0x1a186,7,"even WORD/LONG"},{0x1a1be,7,"even WORD/LONG"},{0x1a200,0,"alignment"},{0x19e60,1,"alignment"},{0x19772,5,"alignment"},
  {0x19796,1,"even WORD/LONG"},{0x1a470,0,"even WORD/LONG"},{0x1a492,0,"even WORD/LONG"},{0x1a4da,7,"even WORD/LONG"},{0x1a500,7,"even WORD/LONG"},
  {0x1a51c,0,"even WORD/LONG"},{0x1a40e,5,"alignment"},{0xe8a06,5,"alignment"},{0x16fee,0,"alignment"},{0x3d84,5,"even WORD/LONG"},
  {0x43e08,0,"alignment"},{0x43e22,0,"alignment"},{0x1a1d6,5,"even WORD/LONG"},{0x1a192,1,"even WORD/LONG"}};
 for(unsigned int i=0;i<sizeof(odd)/sizeof(odd[0]);++i){Bytes ram=zero_ram();State s=state(odd[i].pc);s.a[odd[i].reg]|=1U;reject(ram,s,STOP,odd[i].message);}
 // Odd pointers read from the stream: opcode 10 cell (MOVEA.L (A0)), opcode 00 motion record, bbox, and the
 // opcode 04 descriptor read after the bank writes (rolled back with the PVC writes).
 {Bytes ram=zero_ram();put(ram,SP,4,0x1a296);put(ram,SCR,2,0x10);put(ram,SCR+2,4,AUX+1);reject(ram,state(0x1a0b6),0x1a296,"even WORD/LONG");
  put(ram,SCR,2,0x00);put(ram,SCR+6,4,0x10eb01);reject(ram,state(0x1a0b6),0x1a296,"even WORD/LONG");
  Bytes r2=zero_ram();put(r2,0x10d418,2,5);put(r2,0x10d40e,4,REC);put(r2,REC+8,4,BBX+1);reject(r2,state(0x1a442),STOP,"even WORD/LONG");}
 // Odd payload length: the copy loop never reaches 0. It walks up to the end of the RAM mirror and the first
 // write at 200000 fails (the block budget is never reached: A1 leaves RAM after fewer than 2^19 iterations).
 // Record at 100100 (28ae failure object 100e98: copy 100110 -> 100f0e), so the destination leaves RAM first.
 {Bytes ram=zero_ram();put(ram,0x10d40e,4,0x100100);put(ram,0x100102,2,3);reject(ram,state(0x1a442),STOP,"unsupported animation machine write device");}
 // Source leaving first (record 10e400): the read crosses the bank window 200000..200180 and then fails.
 {Bytes ram=zero_ram();put(ram,0x10d40e,4,REC);put(ram,REC+2,2,0xffff);reject(ram,state(0x1a442),STOP,"missing program bus ROM unit");}
}
